259					return runRecallEvidence(cmd, brainDir, resolvedBranch, query, limit, evidenceBytes, jsonOut)
260				}
261				allFacts, err := loadFacts(brainDir, resolvedBranch)
262				if err != nil {
263					return err
264				}
265				// Facts that are not about this repository — preferences, team
266				// conventions, environment details — merge in here, so something
267				// recorded once applies everywhere. They go through every filter
268				// and the same ranking as repository facts; the only difference is
269				// that they are labelled, because acting on a global convention as
270				// though this repo had declared it is a different thing.
271				globalIDs := map[string]bool{}
272				if globalFactsEnabled(noGlobal) {
273					globalFacts, globalErr := loadGlobalFacts(opts.Env)
274					if globalErr != nil {
275						// A damaged global store must not take recall down with it;
276						// the repository's own facts are the answer to most queries.
277						fmt.Fprintf(cmd.ErrOrStderr(), "warning: global facts unavailable: %v\n", globalErr)
278					} else {
279						allFacts, globalIDs = mergeGlobalFacts(allFacts, globalFacts)
280					}
281				}
282				var storeWarning string
283				manifest, manifestErr := loadBrainManifest(brainDir)
284				if manifestErr != nil {
285					storeWarning = "fact source manifest unavailable: " + manifestErr.Error()
286				} else if manifest != nil && manifest.Sources != nil {
287					storeWarning = missingFactStoreWarningForBranch(brainDir, manifest.Sources.Facts, resolvedBranch)
288				}
289				candidateFacts := allFacts
290				var eligibility *factEligibilityAudit
291				if eligibleBefore != "" || sessionDatesPath != "" || len(excludeSessionIDs) > 0 {
292					if eligibleBefore == "" || sessionDatesPath == "" {
293						return fmt.Errorf("--eligible-before and --session-dates must be supplied together")
294					}
295					dates, loadErr := loadSessionDates(sessionDatesPath)
296					if loadErr != nil {
297						return loadErr
298					}
299					filtered, audit, filterErr := filterFactsByTemporalEligibility(allFacts, dates, eligibleBefore, excludeSessionIDs)
300					if filterErr != nil {
301						return filterErr
302					}
303					candidateFacts = filtered
304					eligibility = &audit
305				}
306				facts := filterFactsByLocus(filterFactsByKind(filterFactsByScope(candidateFacts, scope), kind), locus)
307				effectiveQuery := query
308				if expand && strings.TrimSpace(query) != "" {
309					resolved := agent
310					if resolved == "auto" {
311						resolved = defaultRefreshAgent(cmd.Context(), opts.Runner, repoDir)
312					}
313					expandArgs, expErr := distillAgentCommandArgs(resolved, agentCommand, queryExpansionPrompt())
314					if expErr != nil {
