316					}
317					expandArgs = injectAgentModel(expandArgs, resolved, model)
318					exp, expErr := expandQuery(cmd.Context(), defaultDistillAgentRunner(resolved), expandArgs, repoDir, query, loadExpansionCache(""))
319					if expErr != nil {
320						return fmt.Errorf("expand query: %w", expErr)
321					}
322					effectiveQuery = expandedQuery(query, exp)
323				}
324				// Semantic rerank is on by default (the measured Phase D win); it
325				// degrades silently to lexical when the embedder can't load, so a
326				// missing/corrupt model never breaks recall. The disk-backed cache
327				// avoids re-embedding the branch on every invocation.
328				var rr *semanticReranker
329				if !noSemantic {
330					if e := resolveEmbedder(); e != nil {
331						rr = newSemanticRerankerForBranch(e, brainDir, resolvedBranch)
332						// One mechanism for this, shared with query/search and
333						// brief: the reranker itself refuses to cache or retain a
334						// fact that belongs to every repository. The manual filter
335						// at retain below only covered half of it — factVector
336						// caches and marks a fact touched while ranking, before
337						// retain is ever reached.
338						rr.markForeign(globalIDs)
339					}
340				}
