74		if err != nil {
75			return memoryVectorProgress{}, present, newMemoryVectorProgressLoadError(err, 0)
76		}
77		if !present {
...
99		}
100		var progress memoryVectorProgress
101		if _, err := decodeVersionedJSONBody(data, &progress, false); err != nil {
102			if errors.Is(err, errTrailingJSONData) {
103				return memoryVectorProgress{}, newMemoryVectorProgressLoadError(fmt.Errorf("vector progress has trailing JSON data"), header.SchemaVersion)
104			}
105			return memoryVectorProgress{}, newMemoryVectorProgressLoadError(err, header.SchemaVersion)
106		}
