1	package cli
2	
3	import (
4		"testing"
5		"time"
6	)
7	
8	func bm25Fact(id, text string, paths ...string) factRecord {
9		if len(paths) == 0 {
10			paths = []string{"architecture.test"}
11		}
12		return factRecord{
13			ID: id, Text: text, Paths: paths,
14			Status: factStatusActive, UpdatedAt: time.Now(),
15		}
16	}
17	
18	// A document holding the query's rare term must outrank one matching only the
19	// common term, even when the common-term document repeats it. This is the
20	// measured failure of the flat scorer at corpus scale (term collisions), and
21	// the reason BM25 replaces it.
22	func TestBM25RareTermOutranksCommon(t *testing.T) {
23		facts := []factRecord{
24			bm25Fact("fact:common1", "the sync loop retries sync requests with sync batching"),
25			bm25Fact("fact:common2", "sync clients refresh tokens before sync windows"),
26			bm25Fact("fact:common3", "sync state is cached between sync runs"),
27			bm25Fact("fact:rare", "sync retries use exponential backoff with jitter"),
28		}
29		got := rankFacts(facts, "sync backoff", 2, false)
30		if len(got) == 0 || got[0].ID != "fact:rare" {
31			t.Fatalf("expected fact:rare first, got %+v", factIDs(got))
32		}
33	}
34	
35	// Term repetition saturates: a fact matching two distinct query terms beats a
36	// fact stuffing one term many times.
37	func TestBM25SaturationPrefersDistinctTerms(t *testing.T) {
38		facts := []factRecord{
39			bm25Fact("fact:stuffed", "distill distill distill distill distill distill distill distill"),
40			bm25Fact("fact:both", "the distill pipeline writes a manifest after each run"),
41		}
42		got := rankFacts(facts, "distill manifest", 2, false)
43		if len(got) == 0 || got[0].ID != "fact:both" {
44			t.Fatalf("expected fact:both first, got %+v", factIDs(got))
45		}
46	}
47	
48	// With equal term evidence, the shorter fact ranks first (length
49	// normalization), and recency still breaks exact ties.
50	func TestBM25LengthNormalization(t *testing.T) {
51		long := "the embedder loads lazily on first query and caches vectors per branch " +
52			"while unrelated sentences about many other subsystems pad this fact out " +
53			"with words that do not touch the query at all in any way whatsoever"
54		facts := []factRecord{
55			bm25Fact("fact:long", long),
56			bm25Fact("fact:short", "the embedder caches vectors per branch"),
57		}
58		got := rankFacts(facts, "embedder vectors", 2, false)
59		if len(got) == 0 || got[0].ID != "fact:short" {
60			t.Fatalf("expected fact:short first, got %+v", factIDs(got))
61		}
62	}
63	
64	// The locus boost survives the BM25 rewrite: a shared code identifier still
65	// lifts a fact above a plain-text match of similar strength.
